fn append_vectors<T: Copy>(v1: &Vec<T>, v2: &Vec<T>) -> Vec<T> {
    let mut result = Vec::with_capacity(v1.len() + v2.len());
    // Append all elements of v1
    result.extend_from_slice(&v1[..]);
    // Append all elements of v2
    result.extend_from_slice(&v2[..]);
    result
}

fn replace_last_element(first: &Vec<i32>, second: &Vec<i32>) -> Vec<i32> {
    assert!(!first.is_empty(), "The first vector must be non-empty.");

    // Take all elements of `first` except the last element
    let prefix = &first[..first.len() - 1];

    // Use the generic append_vectors to concatenate prefix + second
    append_vectors(&prefix.to_vec(), second)
}